referenceSolutions.javascript:
export function longestPalindromeSubstring(text        )         {
let start=0,best=0;for(let c=0;c<text.length;c++)for(const offset of [0,1]){let l=c,r=c+offset;while(l>=0&&r<text.length&&text[l]===text[r]){if(r-l+1>best){start=l;best=r-l+1;}l--;r++;}}return text.slice(start,start+best);
}

